var e=`1413-faikakai`;var n=`world-1413`;var o=`TO`;var t=`oceania`;var r=6;var s=45;var u={en:`Faikakai`,ua:`Файкакай`};var l={en:`Faikakai are Tongan starchy dumplings served with a warm sweet coconut sauce; this version uses cassava flour.`,ua:`Файкакай, тонганські крохмалисті кльоцки, які подають із теплим солодким кокосовим соусом; ця версія використовує маніокове борошно.`};var g=[{en:`Mix cassava flour, all-purpose flour and salt. Add warm water gradually to form a soft, shapeable dough.`,ua:`Змішайте маніокове й пшеничне борошно із сіллю. Поступово додайте теплу воду, щоб отримати м’яке тісто, яке тримає форму.`,t:[`mixing`],m:9,i:[[`cassava-flour`,240,`g`],[`all-purpose-flour`,80,`g`],[`sea-salt`,3,`g`],[`water`,240,`ml`]]},{en:`Divide dough into 18 small rounded dumplings. Bring a wide pot of water to a gentle boil.`,ua:`Поділіть тісто на 18 невеликих округлих кльоцок. Доведіть воду в широкій каструлі до слабкого кипіння.`,t:[`pre-shaping-dough`],m:8,i:[[`water`,1300,`ml`]]},{en:`Boil dumplings in batches for 12–15 minutes until firm and cooked to the centre; drain.`,ua:`Варіть кльоцки порціями 12–15 хвилин, доки вони не стануть пружними й повністю готовими всередині; відцідіть.`,t:[`boiling`,`draining`],m:15,i:[]},{en:`Simmer coconut cream with brown sugar for 8–10 minutes, stirring until syrupy. Do not let it scorch.`,ua:`Томіть кокосові вершки з коричневим цукром 8–10 хвилин, помішуючи, до густого сиропу. Не допускайте пригорання.`,t:[`sugar-syrup-cooking`],m:10,i:[[`coconut-cream`,380,`ml`],[`brown-sugar`,155,`g`]]},{en:`Coat warm dumplings in the coconut sauce and serve at once.`,ua:`Змішайте теплі кльоцки з кокосовим соусом і одразу подавайте.`,t:[`mixing`],m:3,i:[]}];var m={slug:e,id:n,country:`TO`,region:t,servings:6,minutes:45,title:u,text:l,steps:g};export{o as country,m as default,n as id,s as minutes,t as region,r as servings,e as slug,g as steps,l as text,u as title};